use kimo_core::threed::{mesh::{Mesh,Node,IDENTITY,world_matrices},spatial::{Bvh,Ray,brute_force},sdf::Field,pbr::{Material,sample},cpu,backend};
fn triangle()->Mesh{Mesh{positions:vec![[-0.8,-0.8,0.5],[0.8,-0.8,0.5],[0.0,0.8,0.5]],indices:vec![[0,1,2]]}}
#[test]fn mesh_validation_and_hierarchy_cycles(){let mut m=triangle();assert_eq!(m.bounds().unwrap(),[[-0.8,-0.8,0.5],[0.8,0.8,0.5]]);m.indices[0][0]=99;assert!(m.validate().is_err());let n=Node{parent:Some(0),local:IDENTITY,mesh:None};assert!(world_matrices(&[n],0).is_err());let mut local=IDENTITY;local[0][3]=2.0;let nodes=[Node{parent:None,local,mesh:Some(0)},Node{parent:Some(0),local,mesh:None}];assert_eq!(world_matrices(&nodes,1).unwrap()[1][0][3],4.0);}
#[test]fn bvh_matches_triangle_oracle_grid(){let m=triangle();let b=Bvh::build(&m).unwrap();for y in -12..=12{for x in -12..=12{let r=Ray{origin:[x as f64/10.0,y as f64/10.0,0.0],direction:[0.,0.,1.],t_min:0.,t_max:2.};let fast=b.raycast(&m,&r).unwrap();let slow=brute_force(&m,&r).unwrap();assert_eq!(fast.as_ref().map(|h|h.triangle),slow.as_ref().map(|h|h.triangle));if let (Some(a),Some(b))=(fast,slow){assert!((a.t-b.t).abs()<1e-14);}}}}
#[test]fn sdf_analytic_and_csg(){let a=Field::Sphere{center:[0.;3],radius:1.};assert_eq!(a.sample([0.;3]).unwrap(),-1.);assert_eq!(a.sample([2.,0.,0.]).unwrap(),1.);let b=Field::Box{center:[0.;3],half_size:[0.5;3]};let c=Field::Subtract{a:Box::new(a),b:Box::new(b)};assert_eq!(c.sample([0.;3]).unwrap(),0.5);}
#[test]fn pbr_finite_metal_diffuse_zero_and_backface(){for metallic in [0.,1.]{let m=Material{albedo:[0.5;3],metallic,roughness:0.5};let b=sample(&m,[0.,0.,1.],[0.,0.,1.],[0.,0.,1.]).unwrap();assert!(b.specular.iter().chain(b.diffuse.iter()).all(|v|v.is_finite()&&*v>=0.));if metallic==1.{assert_eq!(b.diffuse,[0.;3]);}assert_eq!(sample(&m,[0.,0.,1.],[0.,0.,-1.],[0.,0.,1.]).unwrap().specular,[0.;3]);}}
#[test]fn cpu_buffer_depth_and_readback_layout(){let (f,d)=cpu::render(&triangle(),64,32,[2.,-1.,0.,1.]).unwrap();assert_eq!(f.d.len(),64*32*4);assert!(f.d.iter().all(|v|v.is_finite()));assert!(d.iter().any(|v|*v==0.5));assert_eq!(backend::readback_layout(17,2).unwrap(),(512,1024));}
#[cfg(feature="mesh-import")]
#[test]fn obj_parser_triangle_and_unsupported_face(){let m=kimo_core::threed::import::obj("v 0 0 0\nv 1 0 0\nv 0 1 0\nf 1 2 3\n").unwrap();assert_eq!(m[0].indices,vec![[0,1,2]]);assert!(kimo_core::threed::import::obj("f 1 2 3 4\n").is_err());}
#[test]#[ignore="actual1080p PNG proof after serial compile and unit gates"]
fn render_1080p_foundation_fixture(){let path=std::env::var("KIMO_3D_FRAME").expect("PNG path");let (f,_)=cpu::render(&triangle(),1920,1080,[0.2,0.7,0.9,1.]).unwrap();let bytes=kimo_core::render::to_rgba8(&f);use std::io::Write;let mut child=std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s","1920x1080","-i","-","-frames:v","1",&path]).stdin(std::process::Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();assert!(child.wait().unwrap().success());}
